using System;using System.Collections.Concurrent;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using Microsoft.Extensions.Logging;namespace MagnumOpus.Core{public record Transaction(string Id,string From,string To,decimal Amount,string Symbol,DateTime Timestamp);public interface ITransactionProcessor{Task<string> SubmitAsync(Transaction tx);Task<IReadOnlyCollection<Transaction>> GetPendingAsync();Task ProcessPendingAsync(CancellationToken ct);}public class TransactionProcessor:ITransactionProcessor{private readonly ILogger<TransactionProcessor> _logger;private readonly ConcurrentQueue<Transaction> _queue=new();private readonly TimeSpan _processingInterval=TimeSpan.FromSeconds(2);public TransactionProcessor(ILogger<TransactionProcessor> logger){_logger=logger;}public Task<string> SubmitAsync(Transaction tx){_queue.Enqueue(tx);_logger.LogInformation("Transaction {Id} enqueued",tx.Id);return Task.FromResult(tx.Id);}public Task<IReadOnlyCollection<Transaction>> GetPendingAsync()=>Task.FromResult((IReadOnlyCollection<Transaction>)_queue.ToArray());public async Task ProcessPendingAsync(CancellationToken ct){_logger.LogInformation("Transaction processor started");while(!ct.IsCancellationRequested){if(_queue.IsEmpty){await Task.Delay(_processingInterval,ct);continue;}var batch=new List<Transaction>();while(_queue.TryDequeue(out var tx))batch.Add(tx);foreach(var tx in batch){try{await SimulateOnChainAsync(tx,ct);_logger.LogInformation("Processed tx {Id}",tx.Id);}catch(Exception ex){_logger.LogError(ex,"Failed tx {Id}",tx.Id);}}await Task.Delay(_processingInterval,ct);} _logger.LogInformation("Transaction processor stopped");}private async Task SimulateOnChainAsync(Transaction tx,CancellationToken ct){await Task.Delay(TimeSpan.FromMilliseconds(new Random().Next(100,500)),ct);var hash=Convert.ToHexString(System.Text.Encoding.UTF8.GetBytes($"{tx.Id}{DateTime.UtcNow.Ticks}"));_logger.LogDebug("Tx {Id} simulated on-chain hash {Hash}",tx.Id,hash);}}}